const before = await page.evaluate(() => window.__goldenAce.state.bankroll);
await page.locator('.rail-chip[data-value="25"]').click();
// Force a deterministic deck: player gets A+10 (blackjack), dealer 17.
await page.evaluate(() => { Math.random = () => 0; });
