  phase: window.__goldenAce.state.phase,
  busy: window.__goldenAce.state.busy,
  status: document.getElementById('statusText').textContent,
  banner: document.getElementById('banner').textContent,
  primaryDisabled: document.getElementById('primaryBtn').disabled,
  hand: window.__goldenAce.state.hands.player.map(c => c.rank + c.suit),
  dealer: window.__goldenAce.state.hands.dealer.map(c => c.hidden ? '??' : c.rank + c.suit),
}));
console.log('mid', mid);
await page.screenshot({ path: 'screenshots/blackjack-mid.jpg', type: 'jpeg', quality: 84 });
await page.waitForFunction(() => window.__goldenAce.state.phase === 'result', null, { timeout: 25000 });
await page.waitForTimeout(400);
const after = await page.evaluate(() => ({
  bankroll: window.__goldenAce.state.bankroll,
  outcome: window.__goldenAce.state.outcomes.player,
  dealer: window.__goldenAce.state.hands.dealer.map(c => c.rank + c.suit),
  status: document.getElementById('statusText').textContent,
  banner: document.getElementById('banner').textContent,
  primary: document.getElementById('primaryBtn').textContent,
  hand: window.__goldenAce.state.hands.player.map(c => c.rank + c.suit),
}));
console.log('before', before, 'after', after, 'delta', after.bankroll - before, 'elapsed', Date.now() - t0);
await page.screenshot({ path: 'screenshots/blackjack-result.jpg', type: 'jpeg', quality: 84 });
console.log('errors:', errors.length ? errors : 'none');
