803:   function settle() {
804:     const dealerValue = valueOf(state.hands.dealer);
805:     const dealerTotal = dealerValue.total;
806:     const dealerBJ = state.hands.dealer.length === 2 && dealerTotal === 21;
807:     const playerHand = state.hands.player;
808:     const playerValue = valueOf(playerHand);
809:     const playerBJ = playerHand.length === 2 && playerValue.total === 21;
810:     const playerBust = playerValue.total > 21;
811: 
812:     state.phase = 'result';
813:     state.busy = false;
814:     state.outcomes = {};
815: 
816:     let totalReturned = 0;
817: 
818:     for (const key of KEYS) {
819:       const bet = state.bets[key];
820:       if (!bet) continue;
821:       const v = valueOf(state.hands[key]);
822:       const bust = v.total > 21;
823:       const bj = state.hands[key].length === 2 && v.total === 21;
824:       let returned = 0;
825:       let net = -bet;
826:       let cls = 'lose';
827: 
828:       if (bust) {
829:         net = -bet;
830:         cls = 'lose';
831:       } else if (dealerBJ) {
832:         if (bj) { returned = bet; net = 0; cls = 'push'; }
833:         else { net = -bet; cls = 'lose'; }
834:       } else if (bj) {
835:         returned = Math.round(bet * 2.5 * 100) / 100;
836:         net = Math.round((returned - bet) * 100) / 100;
837:         cls = 'win';
838:       } else if (dealerTotal > 21 || v.total > dealerTotal) {
839:         returned = bet * 2;
840:         net = bet;
841:         cls = 'win';
842:       } else if (v.total === dealerTotal) {
843:         returned = bet;
844:         net = 0;
845:         cls = 'push';
846:       } else {
847:         net = -bet;
848:         cls = 'lose';
849:       }
850: 
851:       returned = Math.round(returned * 100) / 100;
852:       net = Math.round(net * 100) / 100;
853: 
854:       if (key === 'player') {
855:         state.bankroll = Math.round((state.bankroll + returned) * 100) / 100;
856:       } else {
857:         state.ai[key].bal += returned;
858:       }
859:       totalReturned += returned;
860: 
861:       state.outcomes[key] = {
862:         cls,
863:         net,
864:         label: cls === 'push' ? 'PUSH' : `${net >= 0 ? '+' : '−'}$${money(Math.abs(net))}`,
865:       };
866:     }
867: 
868:     saveBank();
869:     updateBank();
870:     renderAll(false);
871:     renderBets();
872:     renderControls();
873:     refreshChipStates();
874:     setActive(null);
875:     updateBetReadout();
876: 
877:     const playerOutcome = state.outcomes.player;
878:     if (playerOutcome) {
879:       if (playerOutcome.cls === 'win') {
880:         const main = playerBJ && !dealerBJ ? 'BLACKJACK' : 'YOU WIN';
881:         showBanner(main, 'win', `+$${money(playerOutcome.net)}`);
882:         setStatus(playerBJ && !dealerBJ ? 'BLACKJACK — PAID 3 TO 2' : 'YOU WIN');
883:         Sound.win();
884:         haptic([10, 30, 10, 30, 16]);
885:       } else if (playerOutcome.cls === 'push') {
886:         showBanner('PUSH', 'push');
887:         setStatus('PUSH — BET RETURNED');
888:         Sound.push();
889:         haptic(10);
890:       } else {
891:         showBanner(playerBust ? 'BUST' : 'DEALER WINS', 'lose');
892:         setStatus(playerBust ? `BUST — LOST $${money(state.bets.player)}` : `DEALER WINS — LOST $${money(state.bets.player)}`);
893:         if (!playerBust) Sound.lose();
894:       }
895:     }
896: 
897:     // Reveal dealer result in its caption line.
898:     if (els.captionDealer) {
899:       els.captionDealer.textContent = dealerTotal > 21 ? 'DEALER BUST' : dealerBJ ? 'DEALER BLACKJACK' : 'STANDS ON 17';
900:     }
901: 
902:     if (totalReturned === 0 && state.bankroll < 1) {
903:       setTimeout(() => showToast('Next hand: the house spots you $100'), 1400);
904:     }
905:   }
