818:     for (const key of KEYS) {
819:       const bet = state.bets[key];
820:       if (!bet) continue;
821:       const v = valueOf(state.hands[key]);
822:       const bust = v.total > 21;
823:       const bj = state.hands[key].length === 2 && v.total === 21;
824:       let returned = 0;
825:       let net = -bet;
826:       let cls = 'lose';
827: 
828:       if (bust) {
829:         net = -bet;
830:         cls = 'lose';
831:       } else if (dealerBJ) {
832:         if (bj) { returned = bet; net = 0; cls = 'push'; }
833:         else { net = -bet; cls = 'lose'; }
834:       } else if (bj) {
835:         returned = Math.round(bet * 2.5 * 100) / 100;
836:         net = Math.round((returned - bet) * 100) / 100;
837:         cls = 'win';
838:       } else if (dealerTotal > 21 || v.total > dealerTotal) {
839:         returned = bet * 2;
840:         net = bet;
841:         cls = 'win';
842:       } else if (v.total === dealerTotal) {
843:         returned = bet;
844:         net = 0;
845:         cls = 'push';
846:       } else {
847:         net = -bet;
848:         cls = 'lose';
849:       }
850: 
851:       returned = Math.round(returned * 100) / 100;
852:       net = Math.round(net * 100) / 100;
853: 
854:       if (key === 'player') {
855:         state.bankroll = Math.round((state.bankroll + returned) * 100) / 100;
856:       } else {
857:         state.ai[key].bal += returned;
858:       }
859:       totalReturned += returned;
860: 
861:       state.outcomes[key] = {
862:         cls,
863:         net,
864:         label: cls === 'push' ? 'PUSH' : `${net >= 0 ? '+' : '−'}$${money(Math.abs(net))}`,
865:       };
866:     }
867: 
868:     saveBank();
869:     updateBank();
