879:       if (playerOutcome.cls === 'win') {
880:         const main = playerBJ && !dealerBJ ? 'BLACKJACK' : 'YOU WIN';
881:         showBanner(main, 'win', `+$${money(playerOutcome.net)}`);
882:         setStatus(playerBJ && !dealerBJ ? 'BLACKJACK — PAID 3 TO 2' : 'YOU WIN');
