const { chromium } = require('playwright-core');

(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--disable-dev-shm-usage']
  });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  const out = [];
  const check = (name, ok, extra = '') => {
    out.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? ' — ' + extra : ''}`);
    if (!ok) process.exitCode = 1;
  };

  await page.goto('http://127.0.0.1:8765/index.html');
  await page.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '5000'); });
  await page.reload();
  await page.waitForTimeout(300);

  const baseline = await page.evaluate(() => ({
    felt: getComputedStyle(document.querySelector('.felt')).backgroundImage,
    carpet: getComputedStyle(document.querySelector('.carpet')).backgroundImage,
    chip: getComputedStyle(document.querySelector('.chip.chip-1')).getPropertyValue('--base').trim(),
  }));

  await page.click('#shopBtn');
  await page.waitForTimeout(350);
  const counts = await page.evaluate(() => Object.fromEntries(
    ['chips', 'cards', 'felts', 'floors'].map(c => [c, document.querySelectorAll(`.shop-option[data-category="${c}"]`).length])
  ));
  check('shop has 6 options in every category', Object.values(counts).every(n => n === 6), JSON.stringify(counts));
  check('shop has 24 options total', await page.locator('.shop-option').count() === 24);

  const bank = async () => (await page.textContent('#bankroll')).trim();
  check('starting bankroll shown', await bank() === '$5,000', await bank());

  // Buy + auto-equip one item in each category.
  await page.click('.shop-option[data-category="chips"][data-id="royal"]');
  await page.waitForTimeout(150);
  const chipState = await page.evaluate(() => ({
    bodyClass: document.body.className,
    base: getComputedStyle(document.querySelector('.chip.chip-1')).getPropertyValue('--base').trim(),
    allBases: [...document.querySelectorAll('.chip')].map(c => getComputedStyle(c).getPropertyValue('--base').trim()),
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
  }));
  check('chip set equips body class', chipState.bodyClass.includes('chips-royal'), chipState.bodyClass);
  check('chip set changes every chip color', chipState.allBases.length > 0 && chipState.allBases.every(b => b === '#6337a6'), chipState.allBases.join(','));
  check('chip set converted to CSS variable', chipState.base === '#6337a6', chipState.base);
  check('chip purchase persisted + equipped', (chipState.stored.purchased || []).includes('chips:royal') && chipState.stored.equipped?.chips === 'royal', JSON.stringify(chipState.stored));
  check('chip purchase deducted $150', await bank() === '$4,850', await bank());

  await page.click('.shop-option[data-category="cards"][data-id="noir"]');
  await page.waitForTimeout(150);
  check('card set equips body class', (await page.evaluate(() => document.body.className)).includes('cards-noir'));
  check('card purchase deducted $180', await bank() === '$4,670', await bank());

  await page.click('.shop-option[data-category="felts"][data-id="black"]');
  await page.waitForTimeout(150);
  const feltAfter = await page.evaluate(() => ({
    cls: document.body.className,
    img: getComputedStyle(document.querySelector('.felt')).backgroundImage,
  }));
  check('felt set equips body class', feltAfter.cls.includes('felt-black'), feltAfter.cls);
  check('felt background actually changes', feltAfter.img !== baseline.felt, feltAfter.img.slice(0, 100));
  check('felt purchase deducted $180', await bank() === '$4,490', await bank());

  await page.click('.shop-option[data-category="floors"][data-id="diamond"]');
  await page.waitForTimeout(150);
  const floorAfter = await page.evaluate(() => ({
    cls: document.body.className,
    img: getComputedStyle(document.querySelector('.carpet')).backgroundImage,
  }));
  check('floor set equips body class', floorAfter.cls.includes('floor-diamond'), floorAfter.cls);
  check('floor background actually changes', floorAfter.img !== baseline.carpet, floorAfter.img.slice(0, 100));
  check('floor purchase deducted $150', await bank() === '$4,340', await bank());

  check('only one variant class per category', await page.evaluate(() => {
    const cls = document.body.className.split(/\s+/);
    return ['chips-', 'cards-', 'felt-', 'floor-'].every(p => cls.filter(c => c.startsWith(p)).length === 1);
  }));

  // Equipping an already-owned item must not charge again.
  await page.click('.shop-option[data-category="chips"][data-id="classic"]');
  await page.waitForTimeout(120);
  check('re-equipping default is free', await bank() === '$4,340', await bank());
  await page.click('.shop-option[data-category="chips"][data-id="royal"]');
  await page.waitForTimeout(120);
  check('re-equipping owned set is free', await bank() === '$4,340', await bank());
  check('owned set re-applies', (await page.evaluate(() => document.body.className)).includes('chips-royal'));

  // Deal a hand and inspect live card face + back styling.
  await page.click('#shopDone');
  await page.waitForTimeout(350);
  await page.click('.rail-chip.chip-25');
  await page.waitForTimeout(250);
  await page.click('#primaryBtn');
  await page.waitForTimeout(1200);
  const cards = await page.evaluate(() => {
    const face = document.querySelector('.seat.player .card:not(.back)');
    const back = document.querySelector('.seat.dealer .card.back');
    return {
      phase: window.__goldenAce?.state.phase,
      faceBg: face ? getComputedStyle(face).backgroundImage : null,
      faceColor: face ? getComputedStyle(face).color : null,
      backBg: back ? getComputedStyle(back).backgroundImage : null,
      backAfter: back ? getComputedStyle(back, '::after').content : null,
    };
  });
  check('round reached player phase', cards.phase === 'player', cards.phase);
  check('dealt card face uses Noir style', !!cards.faceBg && cards.faceBg.includes('rgb(48, 52, 59)'), (cards.faceBg || '').slice(0, 120));
  check('dealt card back uses Noir style', !!cards.backBg && cards.backBg.includes('rgb(38, 42, 49)'), (cards.backBg || '').slice(0, 120));
  check('card back emblem matches set', cards.backAfter.includes('◆'), cards.backAfter);

  // Persistence across reload.
  await page.reload();
  await page.waitForTimeout(400);
  const persisted = await page.evaluate(() => ({
    cls: document.body.className,
    bank: document.querySelector('#bankroll').textContent.trim(),
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
  }));
  check('equipped looks survive reload', ['chips-royal', 'cards-noir', 'felt-black', 'floor-diamond'].every(c => persisted.cls.includes(c)), persisted.cls);
  check('bankroll survives reload', persisted.bank === '$4,340', persisted.bank);
  check('purchase history survives reload', ['chips:royal', 'cards:noir', 'felts:black', 'floors:diamond'].every(k => persisted.stored.purchased.includes(k)), JSON.stringify(persisted.stored.purchased));

  await page.click('#shopBtn');
  await page.waitForTimeout(300);
  check('shop shows purchased items as equipped after reload', await page.evaluate(() =>
    ['chips:royal', 'cards:noir', 'felts:black', 'floors:diamond'].every(k => {
      const [c, i] = k.split(':');
      return document.querySelector(`.shop-option[data-category="${c}"][data-id="${i}"]`)?.classList.contains('equipped');
    })
  ));
  await page.screenshot({ path: '/tmp/opencode/pwtest/shop-mobile.png' });

  // Insufficient funds test.
  await page.evaluate(() => { window.__goldenAce.state.bankroll = 1; });
  await page.click('.shop-option[data-category="chips"][data-id="midnight"]');
  await page.waitForTimeout(150);
  const poor = await page.evaluate(() => ({
    cls: document.body.className,
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
    toast: document.querySelector('#toast').textContent.trim(),
  }));
  check('unaffordable item is not equipped', !poor.cls.includes('chips-midnight'));
  check('unaffordable item is not purchased', !poor.stored.purchased.includes('chips:midnight'));
  check('unaffordable item shows clear message', /Need \$500/.test(poor.toast), poor.toast);

  check('no runtime errors', errors.length === 0, errors.join(' | '));

  console.log(out.join('\n'));
  await browser.close();
})();

