const { chromium } = require('playwright-core');

const SETS = {
  chips:  ['classic', 'royal', 'ruby', 'ocean', 'gold', 'midnight'],
  cards:  ['classic', 'noir', 'rose', 'emerald', 'blue', 'royal'],
  felts:  ['classic', 'black', 'burgundy', 'blue', 'violet', 'champagne'],
  floors: ['classic', 'diamond', 'checker', 'art', 'red', 'neon'],
};

(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--disable-dev-shm-usage']
  });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  let failures = 0;
  const check = (name, ok, extra = '') => {
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? ' — ' + extra : ''}`);
    if (!ok) failures += 1;
  };

  await page.goto('http://127.0.0.1:8765/index.html');
  await page.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '20000'); });
  await page.reload();
  await page.waitForTimeout(300);

  const shopOption = (cat, id) => `.shop-option[data-category="${cat}"][data-id="${id}"]`;
  const bodyClass = () => page.evaluate(() => document.body.className);
  const bank = async () => (await page.textContent('#bankroll')).trim();
  const snapshot = () => page.evaluate(() => {
    const felt = document.querySelector('.felt');
    const carpet = document.querySelector('.carpet');
    const chip = document.querySelector('.chip.chip-5');
    const probe = document.createElement('div');
    probe.className = 'card';
    felt.appendChild(probe);
    const face = getComputedStyle(probe).backgroundImage;
    probe.className = 'card back';
    const back = getComputedStyle(probe).backgroundImage;
    probe.remove();
    return {
      cls: document.body.className,
      chipBase: getComputedStyle(chip).getPropertyValue('--base').trim(),
      chipEdge: getComputedStyle(chip).getPropertyValue('--edge').trim(),
      felt: getComputedStyle(felt).backgroundImage,
      carpet: getComputedStyle(carpet).backgroundImage,
      cardFace: face,
      cardBack: back,
      overflow: document.documentElement.scrollWidth > innerWidth || document.documentElement.scrollHeight > innerHeight,
    };
  });

  await page.click('#shopBtn');
  await page.waitForTimeout(350);

  // Category structure.
  for (const [cat, ids] of Object.entries(SETS)) {
    const found = await page.evaluate(c => [...document.querySelectorAll(`.shop-option[data-category="${c}"]`)].map(el => el.dataset.id), cat);
    check(`${cat}: exactly 6 options`, found.length === 6, found.join(','));
    check(`${cat}: expected option ids`, JSON.stringify(found) === JSON.stringify(ids), found.join(','));
  }
  check('24 shop options total', await page.locator('.shop-option').count() === 24);

  const jobBtnBox = await page.locator('#shopDone').boundingBox();
  check('shop done button inside mobile viewport', !!jobBtnBox && jobBtnBox.y + jobBtnBox.height <= 844, JSON.stringify(jobBtnBox));

  // Check every option, including buying all 5 paid ones in each category.
  const seen = { chips: new Set(), cards: new Set(), felts: new Set(), floors: new Set() };
  let expectedBank = 20000;
  for (const [cat, ids] of Object.entries(SETS)) {
    for (const id of ids) {
      const priceText = await page.evaluate(sel => document.querySelector(sel)?.querySelector('small')?.textContent.trim(), shopOption(cat, id));
      const price = id === 'classic' ? 0 : Number(priceText.replace(/[^0-9.]/g, ''));
      const before = await bank();

      await page.click(shopOption(cat, id));
      await page.waitForTimeout(120);
      expectedBank -= price;

      const s = await snapshot();
      const equipped = s.cls.includes(`${cat === 'cards' ? 'cards' : cat === 'chips' ? 'chips' : cat === 'felts' ? 'felt' : 'floor'}-${id}`);
      check(`${cat}/${id}: equips live`, equipped, s.cls);
      check(`${cat}/${id}: bankroll ${price ? `drops by $${price}` : 'unchanged'}`, await bank() === `$${expectedBank.toLocaleString('en-US')}`, `${before} -> ${await bank()}, expected $${expectedBank.toLocaleString('en-US')}`);

      const styleKey = cat === 'chips' ? `${s.chipBase}|${s.chipEdge}` : cat === 'cards' ? `${s.cardFace}|${s.cardBack}` : cat === 'felts' ? s.felt : s.carpet;
      check(`${cat}/${id}: has a distinct rendered style`, !seen[cat].has(styleKey), styleKey.slice(0, 90));
      seen[cat].add(styleKey);

      const stored = await page.evaluate(() => JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'));
      check(`${cat}/${id}: saved as equipped`, stored.equipped?.[cat] === id, JSON.stringify(stored.equipped));
      if (id !== 'classic') {
        check(`${cat}/${id}: recorded as purchased`, stored.purchased?.includes(`${cat}:${id}`), JSON.stringify(stored.purchased));
      }
    }
  }

  // Every chip changes with the set, not just one chip.
  await page.click(shopOption('chips', 'ocean'));
  await page.waitForTimeout(100);
  const chipBases = await page.evaluate(() => [...document.querySelectorAll('.chip')].map(c => getComputedStyle(c).getPropertyValue('--base').trim()));
  check('chip set recolors every chip on the table', chipBases.length > 5 && chipBases.every(v => v === '#176fa4'), chipBases.join(','));

  // Re-equip owned/default never charges.
  const bankBeforeReequip = await bank();
  await page.click(shopOption('cards', 'classic'));
  await page.waitForTimeout(100);
  await page.click(shopOption('cards', 'noir'));
  await page.waitForTimeout(100);
  check('re-equipping owned items never charges', await bank() === bankBeforeReequip, `${bankBeforeReequip} -> ${await bank()}`);

  // Persistence after reload, before betting.
  await page.reload();
  await page.waitForTimeout(400);
  const persisted = await page.evaluate(() => ({
    cls: document.body.className,
    bank: document.querySelector('#bankroll').textContent.trim(),
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
  }));
  check('all equipped looks survive reload', ['chips-ocean', 'cards-noir', 'felt-champagne', 'floor-neon'].every(c => persisted.cls.includes(c)), persisted.cls);
  check('bankroll survives reload', persisted.bank === `$${expectedBank.toLocaleString('en-US')}`, persisted.bank);
  check('no document overflow after reload', await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.documentElement.scrollHeight <= innerHeight));

  await page.click('#shopBtn');
  await page.waitForTimeout(300);
  const equippedMarks = await page.evaluate(() => [...document.querySelectorAll('.shop-option.equipped')].map(el => `${el.dataset.category}:${el.dataset.id}`));
  check('shop marks the saved items equipped', JSON.stringify(equippedMarks.sort()) === JSON.stringify(['cards:noir', 'chips:ocean', 'felts:champagne', 'floors:neon']), equippedMarks.join(','));
  await page.screenshot({ path: '/tmp/opencode/pwtest/shop-mobile.png' });
  await page.click('#shopDone');
  await page.waitForTimeout(350);

  // Deal a hand and inspect the live faces + backs.
  await page.click('.rail-chip[data-value="25"]');
  await page.waitForTimeout(200);
  await page.click('#primaryBtn');
  await page.waitForSelector('.seat.dealer .card.back', { timeout: 8000 });
  await page.waitForFunction(() => window.__goldenAce?.state.phase === 'player', null, { timeout: 8000 });
  const cards = await page.evaluate(() => {
    const face = document.querySelector('.seat.player .card:not(.back)');
    const back = document.querySelector('.seat.dealer .card.back');
    return {
      phase: window.__goldenAce?.state.phase,
      faceBg: face ? getComputedStyle(face).backgroundImage : '',
      backBg: back ? getComputedStyle(back).backgroundImage : '',
      backAfter: back ? getComputedStyle(back, '::after').content : '',
      chipBase: getComputedStyle(document.querySelector('.betspot .chip')).getPropertyValue('--base').trim(),
    };
  });
  check('round reaches player phase', cards.phase === 'player', cards.phase);
  check('dealt face card uses Noir face', cards.faceBg.includes('rgb(48, 52, 59)'), cards.faceBg.slice(0, 100));
  check('dealt back card uses Noir back', cards.backBg.includes('rgb(38, 42, 49)'), cards.backBg.slice(0, 100));
  check('dealt back emblem matches Noir', cards.backAfter.includes('◆'), cards.backAfter);
  check('chips in play use Ocean set', cards.chipBase === '#176fa4', cards.chipBase);

  // Insufficient funds.
  await page.evaluate(() => { window.__goldenAce.state.bankroll = 1; });
  await page.click('#shopBtn');
  await page.waitForTimeout(300);
  await page.click(shopOption('chips', 'midnight'));
  await page.waitForTimeout(150);
  const poor = await page.evaluate(() => ({
    cls: document.body.className,
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
    toast: document.querySelector('#toast').textContent.trim(),
  }));
  check('unaffordable set is not equipped', !poor.cls.includes('chips-midnight'));
  check('unaffordable set is not saved', !poor.stored.purchased.includes('chips:midnight'));
  check('unaffordable set shows a clear message', /Need \$500/.test(poor.toast), poor.toast);

  // Desktop sanity check.
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.waitForTimeout(300);
  check('no overflow on desktop with shop open', await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.documentElement.scrollHeight <= innerHeight));

  check('no runtime errors', errors.length === 0, errors.join(' | '));

  await browser.close();
  console.log(`\n${failures === 0 ? 'ALL CHECKS PASSED' : failures + ' CHECK(S) FAILED'}`);
  process.exitCode = failures === 0 ? 0 : 1;
})();

