input.content:
const { chromium } = require('playwright-core');

(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));

  let failures = 0;
  const check = (name, ok, extra = '') => {
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? ' — ' + extra : ''}`);
    if (!ok) failures++;
  };
  const opt = (c, i) => `.shop-option[data-category="${c}"][data-id="${i}"]`;
  const bank = async () => (await page.textContent('#bankroll')).trim();
  const cls = () => page.evaluate(() => document.body.className);

  await page.goto('http://127.0.0.1:8765/index.html');
  await page.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '500'); });
  await page.reload();
  await page.waitForTimeout(250);

  // Commit $400 to a bet, leaving $100 spendable.
  for (let i = 0; i < 4; i++) await page.click('.rail-chip[data-value="100"]');
  await page.waitForTimeout(200);
  check('bet committed', await page.evaluate(() => window.__goldenAce.state.playerBet) === 400);

  await page.click('#shopBtn');
  await page.waitForTimeout(300);
  await page.click(opt('chips', 'royal'));
  await page.waitForTimeout(150);
  const blocked = await page.evaluate(() => ({
    cls: document.body.className,
    toast: document.querySelector('#toast').textContent.trim(),
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
  }));
  check('purchase cannot spend money already bet', !blocked.cls.includes('chips-royal') && !(blocked.stored.purchased || []).includes('chips:royal'), blocked.cls);
  check('blocked purchase reports spendable funds only', /\$100 available/.test(blocked.toast), blocked.toast);
  check('blocked purchase leaves bankroll untouched', await bank() === '$500', await bank());

  // Clear bet, then the same purchase succeeds.
  await page.click('#shopDone');
  await page.waitForTimeout(250);
  await page.click('#secondaryBtn');
  await page.waitForTimeout(200);
  check('bet cleared', await page.evaluate(() => window.__goldenAce.state.playerBet) === 0);
  await page.click('#shopBtn');
  await page.waitForTimeout(250);
  await page.click(opt('chips', 'royal'));
  await page.waitForTimeout(150);
  check('purchase succeeds after clearing bet', (await cls()).includes('chips-royal') && await bank() === '$350', `${await cls()} / ${await bank()}`);

  await page.click('#shopDone');
  await page.waitForTimeout(250);
  const rail = await page.evaluate(() => Object.fromEntries(
    [...document.querySelectorAll('.rail-chip')].map(b => [b.dataset.value, b.classList.contains('hide')])
  ));
  check('chip rail updates immediately after purchase', rail['500'] === true && rail['100'] === false, JSON.stringify(rail));

  // Spend the rest while betting, then verify deal never produces a negative bankroll.
  await page.click('.rail-chip[data-value="100"]');
  await page.click('.rail-chip[data-value="100"]');
  await page.click('.rail-chip[data-value="100"]');
  await page.click('.rail-chip[data-value="25"]');
  await page.click('.rail-chip[data-value="25"]');
  await page.waitForTimeout(200);
  check('$350 bet placed', await page.evaluate(() => window.__goldenAce.state.playerBet) === 350);
  await page.click('#shopBtn');
  await page.waitForTimeout(250);
  await page.click(opt('cards', 'noir'));
  await page.waitForTimeout(150);
  check('all funds committed: purchase blocked', !(await cls()).includes('cards-noir'));
  await page.click('#shopDone');
  await page.waitForTimeout(250);
  await page.click('#primaryBtn');
  await page.waitForTimeout(500);
  const afterDeal = await page.evaluate(() => window.__goldenAce.state.bankroll);
  check('bankroll never goes negative after deal', afterDeal >= 0, String(afterDeal));

  // Tampered equipped item without purchase falls back safely.
  await page.evaluate(() => {
    localStorage.setItem('goldenAce.cosmetics.v1', JSON.stringify({
      purchased: ['chips:royal'],
      equipped: { chips: 'gold', cards: 'classic', felts: 'classic', floors: 'classic' }
    }));
  });
  await page.reload();
  await page.waitForTimeout(300);
  check('unowned equipped look falls back to default', !(await cls()).includes('chips-gold'));

  check('no runtime errors', errors.length === 0, errors.join(' | '));
  await browser.close();
  console.log(`\n${failures === 0 ? 'ALL CHECKS PASSED' : failures + ' CHECK(S) FAILED'}`);
  process.exitCode = failures === 0 ? 0 : 1;
})();

