const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await (await browser.newContext({ viewport: { width: 390, height: 844 } })).newPage();
  await page.goto('http://127.0.0.1:8765/index.html');
  await page.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '20000'); });
  await page.reload();
  await page.waitForTimeout(300);
  await page.click('#shopBtn');
  await page.waitForTimeout(350);
  await page.evaluate(() => { document.querySelector('.shop-scroll').scrollTop = 0; });
  await page.screenshot({ path: '/tmp/opencode/pwtest/shop-top.png' });
  await page.evaluate(() => { const s = document.querySelector('.shop-scroll'); s.scrollTop = s.scrollHeight; });
  await page.waitForTimeout(200);
  await page.screenshot({ path: '/tmp/opencode/pwtest/shop-bottom.png' });
  const metrics = await page.evaluate(() => {
    const s = document.querySelector('.shop-scroll');
    const btn = document.querySelector('#shopDone').getBoundingClientRect();
    return { clientHeight: s.clientHeight, scrollHeight: s.scrollHeight, scrollable: s.scrollHeight > s.clientHeight, btnTop: btn.top, vh: innerHeight };
  });
  console.log(JSON.stringify(metrics));
  await browser.close();
})();

