const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  for (const [w, h] of [[390, 844], [360, 640], [320, 568], [844, 390], [1440, 900]]) {
    const context = await browser.newContext({ viewport: { width: w, height: h } });
    const page = await context.newPage();
    await page.goto('http://127.0.0.1:8765/index.html');
    await page.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '20000'); });
    await page.reload();
    await page.waitForTimeout(250);
    await page.click('#shopBtn');
    await page.waitForTimeout(350);
    const m = await page.evaluate(() => {
      const sheet = document.querySelector('.sheet').getBoundingClientRect();
      const done = document.querySelector('#shopDone').getBoundingClientRect();
      const scroll = document.querySelector('.shop-scroll');
      const first = document.querySelector('.shop-option').getBoundingClientRect();
      return {
        sheetTop: Math.round(sheet.top), sheetBottom: Math.round(sheet.bottom),
        doneTop: Math.round(done.top), doneBottom: Math.round(done.bottom),
        scrollH: scroll.clientHeight, scrollable: scroll.scrollHeight > scroll.clientHeight,
        firstOptionVisible: first.top >= 0 && first.bottom <= innerHeight,
        hOverflow: document.documentElement.scrollWidth > innerWidth,
        vOverflow: document.documentElement.scrollHeight > innerHeight,
        vh: innerHeight,
      };
    });
    console.log(`${w}x${h}`, JSON.stringify(m));
    await context.close();
  }
  await browser.close();
})();

