input.content:
const { chromium } = require('playwright-core');

const SETS = {
  chips:  ['classic', 'sunset', 'ocean', 'forest', 'candy', 'royal', 'ruby', 'gold', 'midnight', 'neon'],
  cards:  ['classic', 'noir', 'rose', 'emerald', 'blue', 'royal', 'sunset', 'deco', 'neon', 'cherry'],
  felts:  ['classic', 'black', 'burgundy', 'blue', 'violet', 'champagne', 'sunset', 'lagoon', 'rose', 'galaxy'],
  floors: ['classic', 'diamond', 'checker', 'art', 'red', 'neon', 'constellation', 'fans', 'terrazzo', 'cosmic'],
};
const PRICES = {
  chips:  { sunset:120, ocean:180, forest:240, candy:320, royal:400, ruby:480, gold:560, midnight:680, neon:850 },
  cards:  { noir:160, rose:220, emerald:280, blue:340, royal:420, sunset:520, deco:640, neon:780, cherry:900 },
  felts:  { black:150, burgundy:210, blue:270, violet:340, champagne:420, sunset:520, lagoon:640, rose:760, galaxy:900 },
  floors: { diamond:140, checker:200, art:260, red:340, neon:430, constellation:540, fans:660, terrazzo:800, cosmic:950 },
};

(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  let failures = 0;
  const check = (name, ok, extra = '') => {
    console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? ' — ' + extra : ''}`);
    if (!ok) failures++;
  };
  const opt = (cat, id) => `.shop-option[data-category="${cat}"][data-id="${id}"]`;
  const bodyClass = () => page.evaluate(() => document.body.className);
  const bank = async () => (await page.textContent('#bankroll')).trim();
  const tab = async cat => { await page.click(`[data-shop-tab="${cat}"]`); await page.waitForTimeout(80); };
  const visibleCats = () => page.evaluate(() => [...document.querySelectorAll('[data-shop-category]')].filter(s => !s.hidden).map(s => s.dataset.shopCategory));
  const previewSignature = cat => page.evaluate(c => [...document.querySelectorAll(`#shop${c[0].toUpperCase()}${c.slice(1)} .cosmetic-preview`)].map(p => {
    const s = getComputedStyle(p.querySelector('i'));
    return [s.backgroundImage, s.backgroundColor, s.backgroundSize, s.borderColor].join('|');
  }), cat);

  await page.goto('http://127.0.0.1:8765/index.html');
  await page.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '20000'); });
  await page.reload();
  await page.waitForTimeout(300);

  const snapshot = () => page.evaluate(() => {
    const felt = document.querySelector('.felt');
    const carpet = document.querySelector('.carpet');
    const probe = document.createElement('div');
    probe.className = 'card';
    felt.appendChild(probe);
    const face = getComputedStyle(probe);
    const faceStyle = [face.backgroundImage, face.backgroundColor, face.backgroundSize, face.color].join('|');
    probe.className = 'card back';
    const back = getComputedStyle(probe);
    const backStyle = [back.backgroundImage, back.backgroundColor, back.backgroundSize].join('|');
    probe.remove();
    const chips = ['1', '5', '25', '100', '500'].map(v => {
      const el = document.querySelector(`.rail-chip[data-value="${v}"] .chip`);
      const cs = getComputedStyle(el);
      return [cs.getPropertyValue('--base').trim(), cs.getPropertyValue('--edge').trim(), cs.getPropertyValue('--label').trim()].join('/');
    });
    const f = getComputedStyle(felt);
    const c = getComputedStyle(carpet);
    return {
      cls: document.body.className, chips,
      felt: [f.backgroundImage, f.backgroundSize].join('|'),
      carpet: [c.backgroundImage, c.backgroundSize].join('|'),
      cardFace: faceStyle, cardBack: backStyle,
      overflow: document.documentElement.scrollWidth > innerWidth || document.documentElement.scrollHeight > innerHeight,
    };
  });

  await page.click('#shopBtn');
  await page.waitForTimeout(350);

  check('four category tabs exist', await page.locator('[data-shop-tab]').count() === 4);
  check('only one category is visible at a time', JSON.stringify(await visibleCats()) === JSON.stringify(['chips']), JSON.stringify(await visibleCats()));
  check('40 shop options total', await page.locator('.shop-option').count() === 40);

  for (const [cat, ids] of Object.entries(SETS)) {
    await tab(cat);
    check(`${cat}: its tab shows only its category`, JSON.stringify(await visibleCats()) === JSON.stringify([cat]), JSON.stringify(await visibleCats()));
    const found = await page.evaluate(c => [...document.querySelectorAll(`.shop-option[data-category="${c}"]`)].map(el => el.dataset.id), cat);
    check(`${cat}: exactly 10 options`, found.length === 10 && JSON.stringify(found) === JSON.stringify(ids), found.join(','));
    const previews = await previewSignature(cat);
    check(`${cat}: all 10 previews are visually distinct`, new Set(previews).size === 10, `${new Set(previews).size} unique`);
    const header = await page.textContent(`[data-shop-category="${cat}"] .shop-category-head span`);
    check(`${cat}: header advertises 10`, /10/.test(header), header);
  }

  const seen = { chips: new Set(), cards: new Set(), felts: new Set(), floors: new Set() };
  let expectedBank = 20000;
  for (const [cat, ids] of Object.entries(SETS)) {
    await tab(cat);
    for (const id of ids) {
      const price = PRICES[cat][id] || 0;
      const before = await bank();
      await page.click(opt(cat, id));
      await page.waitForTimeout(90);
      expectedBank -= price;
      const s = await snapshot();
      const prefix = cat === 'cards' ? 'cards' : cat === 'chips' ? 'chips' : cat === 'felts' ? 'felt' : 'floor';
      check(`${cat}/${id}: equips live`, s.cls.includes(`${prefix}-${id}`), s.cls);
      check(`${cat}/${id}: bankroll ${price ? `drops $${price}` : 'stays free'}`, await bank() === `$${expectedBank.toLocaleString('en-US')}`, `${before} -> ${await bank()}`);
      const styleKey = cat === 'chips' ? s.chips.join(',') : cat === 'cards' ? `${s.cardFace}||${s.cardBack}` : cat === 'felts' ? s.felt : s.carpet;
      check(`${cat}/${id}: rendered style is unique`, !seen[cat].has(styleKey), styleKey.slice(0, 80));
      seen[cat].add(styleKey);
      if (cat === 'chips') {
        const bases = s.chips.map(v => v.split('/')[0]);
        check(`${cat}/${id}: five coordinated denomination colours`, new Set(bases).size === 5, bases.join(','));
        check(`${cat}/${id}: every chip changes from classic`, JSON.stringify(bases) !== JSON.stringify(['#e8e2d2', '#bd3b32', '#1c7a4e', '#242525', '#6c3a86']), bases.join(','));
      }
      if (cat === 'cards') {
        check(`${cat}/${id}: face and back both styled`, !!s.cardFace && !!s.cardBack);
      }
      const stored = await page.evaluate(() => JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'));
      check(`${cat}/${id}: saved as equipped`, stored.equipped?.[cat] === id);
      if (id !== 'classic') check(`${cat}/${id}: recorded as purchased`, stored.purchased?.includes(`${cat}:${id}`));
    }
  }
  check('24? no — 36 paid options purchased', await page.evaluate(() => JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1')).purchased.length) === 36);

  // Re-equip is always free.
  const bankBefore = await bank();
  await tab('cards'); await page.click(opt('cards', 'classic')); await page.waitForTimeout(80);
  await page.click(opt('cards', 'cherry')); await page.waitForTimeout(80);
  check('re-equipping owned items is free', await bank() === bankBefore, `${bankBefore} -> ${await bank()}`);

  // Persistence before dealing.
  await page.reload();
  await page.waitForTimeout(400);
  const persisted = await page.evaluate(() => ({
    cls: document.body.className,
    bank: document.querySelector('#bankroll').textContent.trim(),
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
  }));
  check('all final equipped looks survive reload', ['chips-neon', 'cards-cherry', 'felt-galaxy', 'floor-cosmic'].every(c => persisted.cls.includes(c)), persisted.cls);
  check('bankroll survives reload', persisted.bank === `$${expectedBank.toLocaleString('en-US')}`, persisted.bank);
  check('purchases survive reload', ['chips:neon', 'cards:cherry', 'felts:galaxy', 'floors:cosmic'].every(k => persisted.stored.purchased.includes(k)));
  check('no document overflow with tabs and 10 options', await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth && document.documentElement.scrollHeight <= innerHeight));

  await page.click('#shopBtn');
  await page.waitForTimeout(300);
  await tab('chips');
  await page.screenshot({ path: '/tmp/opencode/pwtest/shop-chips-10.png' });
  await tab('cards');
  await page.screenshot({ path: '/tmp/opencode/pwtest/shop-cards-10.png' });
  check('shop marks the saved items equipped', await page.evaluate(() =>
    ['chips:neon', 'cards:cherry', 'felts:galaxy', 'floors:cosmic'].every(k => {
      const [c, i] = k.split(':');
      return document.querySelector(`.shop-option[data-category="${c}"][data-id="${i}"]`)?.classList.contains('equipped');
    })
  ));
  await page.click('#shopDone');
  await page.waitForTimeout(300);

  // Live table: Neon chips, Cherry cards, Galaxy felt, Cosmic floor.
  await page.click('.rail-chip[data-value="25"]');
  await page.waitForTimeout(200);
  await page.click('#primaryBtn');
  await page.waitForSelector('.seat.dealer .card.back', { timeout: 8000 });
  await page.waitForFunction(() => window.__goldenAce?.state.phase === 'player', null, { timeout: 8000 });
  const live = await page.evaluate(() => {
    const face = document.querySelector('.seat.player .card:not(.back)');
    const back = document.querySelector('.seat.dealer .card.back');
    const felt = getComputedStyle(document.querySelector('.felt'));
    const floor = getComputedStyle(document.querySelector('.carpet'));
    return {
      phase: window.__goldenAce?.state.phase,
      faceBg: getComputedStyle(face).backgroundImage,
      backBg: getComputedStyle(back).backgroundImage,
      backAfter: getComputedStyle(back, '::after').content,
      feltBg: felt.backgroundImage,
      floorBg: floor.backgroundImage,
      chipBases: ['1', '5', '25', '100', '500'].map(v => getComputedStyle(document.querySelector(`.rail-chip[data-value="${v}"] .chip`)).getPropertyValue('--base').trim()),
    };
  });
  check('round reaches player phase', live.phase === 'player', live.phase);
  check('Cherry face is applied to dealt cards', live.faceBg.includes('rgb(255, 248, 247)') || live.faceBg.includes('radial-gradient'), live.faceBg.slice(0, 90));
  check('Cherry back is applied to hole card', live.backBg.includes('rgb(101, 28, 58)'), live.backBg.slice(0, 90));
  check('Cherry back emblem is applied', live.backAfter.includes('✿'), live.backAfter);
  check('Galaxy felt is applied', live.feltBg.includes('rgb(90, 63, 158)'), live.feltBg.slice(0, 90));
  check('Cosmic floor is applied', live.floorBg.includes('conic-gradient'), live.floorBg.slice(0, 90));
  check('Neon chips keep coordinated denom colours', new Set(live.chipBases).size === 5, live.chipBases.join(','));
  await page.screenshot({ path: '/tmp/opencode/pwtest/table-10.png' });

  // Insufficient funds in a fresh profile.
  const poorContext = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const poorPage = await poorContext.newPage();
  poorPage.on('pageerror', e => errors.push('poor pageerror: ' + e.message));
  await poorPage.goto('http://127.0.0.1:8765/index.html');
  await poorPage.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '100'); });
  await poorPage.reload();
  await poorPage.waitForTimeout(250);
  await poorPage.click('#shopBtn');
  await poorPage.waitForTimeout(250);
  await poorPage.click(opt('chips', 'neon'));
  await poorPage.waitForTimeout(180);
  const poor = await poorPage.evaluate(() => ({
    cls: document.body.className,
    stored: JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1') || '{}'),
    toast: document.querySelector('#toast').textContent.trim(),
    bank: document.querySelector('#bankroll').textContent.trim(),
  }));
  check('expensive set blocked when unaffordable', !poor.cls.includes('chips-neon') && !(poor.stored.purchased || []).includes('chips:neon'));
  check('unaffordable toast names the price', /Need \$850/.test(poor.toast), poor.toast);
  check('unaffordable click leaves bankroll alone', poor.bank === '$100', poor.bank);
  await poorContext.close();

  // Responsive checks including short landscape.
  for (const [w, h] of [[390, 844], [320, 568], [844, 390], [1440, 900]]) {
    await page.setViewportSize({ width: w, height: h });
    await page.waitForTimeout(200);
    const m = await page.evaluate(() => {
      const sheet = document.querySelector('.sheet').getBoundingClientRect();
      const done = document.querySelector('#shopDone').getBoundingClientRect();
      return {
        sheetTop: Math.round(sheet.top), doneBottom: Math.round(done.bottom), vh: innerHeight,
        hOverflow: document.documentElement.scrollWidth > innerWidth,
        vOverflow: document.documentElement.scrollHeight > innerHeight,
      };
    });
    check(`${w}x${h}: shop fits viewport`, m.sheetTop >= 0 && m.doneBottom <= m.vh && !m.hOverflow && !m.vOverflow, JSON.stringify(m));
  }

  check('no runtime errors', errors.length === 0, errors.join(' | '));
  await browser.close();
  console.log(`\n${failures === 0 ? 'ALL CHECKS PASSED' : failures + ' CHECK(S) FAILED'}`);
  process.exitCode = failures === 0 ? 0 : 1;
})();

