input.content:
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await (await browser.newContext({ viewport: { width: 390, height: 844 } })).newPage();
  await page.goto('http://127.0.0.1:8765/index.html');
  await page.evaluate(() => { localStorage.clear(); localStorage.setItem('goldenAce.bankroll.v1', '20000'); });
  await page.reload();
  await page.waitForTimeout(250);
  await page.click('#shopBtn');
  await page.waitForTimeout(300);
  for (const cat of ['felts', 'floors']) {
    await page.click(`[data-shop-tab="${cat}"]`);
    await page.waitForTimeout(150);
    await page.screenshot({ path: `/tmp/opencode/pwtest/shop-${cat}-10.png` });
  }
  await browser.close();
})();

