input.content:
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
  const page = await (await browser.newContext({ viewport: { width: 390, height: 844 } })).newPage();
  await page.goto('http://127.0.0.1:8765/index.html');
  await page.evaluate(() => {
    localStorage.clear();
    localStorage.setItem('goldenAce.bankroll.v1', '5000');
    localStorage.setItem('goldenAce.cosmetics.v1', JSON.stringify({
      purchased: ['chips:sunset', 'cards:deco', 'felts:sunset', 'floors:fans'],
      equipped: { chips: 'sunset', cards: 'deco', felts: 'sunset', floors: 'fans' }
    }));
  });
  await page.reload();
  await page.waitForTimeout(300);
  for (const v of ['1', '5', '25', '100', '500']) {
    await page.click(`.rail-chip[data-value="${v}"]`);
    await page.waitForTimeout(80);
  }
  await page.click('#primaryBtn');
  await page.waitForFunction(() => window.__goldenAce?.state.phase === 'player', null, { timeout: 8000 });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/pwtest/table-sunset.png' });
  await browser.close();
})();

