(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox', '--autoplay-policy=no-user-gesture-required'] });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') errors.push(message.text()); });
  await page.goto('http://127.0.0.1:4173/', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  if ((await page.locator('#bankroll').innerText()) !== '$500') throw new Error('Unexpected initial bankroll');

  await page.locator('#bankBtn').click();
  if (await page.locator('#codeModal').getAttribute('aria-hidden') !== 'false') throw new Error('Code modal did not open');
  await page.locator('#codeInput').fill('NOPE');
  await page.locator('#codeForm button[type="submit"]').click();
  if ((await page.locator('#codeMessage').innerText()) !== 'Invalid code.') throw new Error('Invalid code was not rejected');
  if (await page.evaluate(() => localStorage.getItem('goldenAce.infinite.v1')) !== null) throw new Error('Invalid code enabled infinite mode');

  await page.locator('#codeInput').fill('DEV_0x8F4B!');
  await page.locator('#codeForm button[type="submit"]').click();
  if ((await page.locator('#bankroll').innerText()) !== '∞') throw new Error('Infinite display not activated');
  await page.waitForTimeout(1000);
  if (await page.locator('#codeModal').getAttribute('aria-hidden') !== 'true') throw new Error('Code modal did not close after activation');

  await page.evaluate(() => { window.__goldenAce.state.bankroll = 0; });
  const railChip = page.locator('.rail-chip').first();
  await railChip.click();
  if (!(await page.locator('#betReadout').innerText()).includes('$')) throw new Error('Bet did not place in infinite mode');
  const betText = await page.locator('#betReadout').innerText();

  await page.locator('#shopBtn').click();
  const shopOption = page.locator('#shopChips .shop-option').nth(1);
  const cosmeticId = await shopOption.getAttribute('data-id');
  await shopOption.click();
  const cosmeticState = await page.evaluate(() => JSON.parse(localStorage.getItem('goldenAce.cosmetics.v1')));
  if (!cosmeticState.purchased.includes(`chips:${cosmeticId}`)) throw new Error('Cosmetic purchase was not persisted');
  if ((await page.locator('#bankroll').innerText()) !== '∞') throw new Error('Shop purchase changed infinite bankroll display');
  await page.locator('#shopDone').click();

  await page.locator('#primaryBtn').click();
  await page.waitForTimeout(4500);
  if ((await page.locator('#bankroll').innerText()) !== '∞') throw new Error('Bankroll display changed after game round');
  await page.reload({ waitUntil: 'networkidle' });
  if ((await page.locator('#bankroll').innerText()) !== '∞') throw new Error('Infinite mode did not persist across reload');
  const persisted = await page.evaluate(() => ({ mode: localStorage.getItem('goldenAce.infinite.v1'), bankroll: localStorage.getItem('goldenAce.bankroll.v1'), cosmetics: localStorage.getItem('goldenAce.cosmetics.v1') }));
  if (persisted.mode !== 'on') throw new Error('Infinite mode storage missing after reload');
  if (!(await page.locator('#shopBtn').isVisible())) throw new Error('Game layout failed to reload');
  if (errors.length) throw new Error(`Browser errors: ${errors.join(' | ')}`);
  console.log(JSON.stringify({ invalidCodeRejected: true, infiniteEnabled: true, betPlacedAtZeroBankroll: betText.trim(), shopPurchasePersisted: true, roundCompleted: true, modePersisted: persisted.mode, savedBankroll: persisted.bankroll, mobileLayoutVisible: true, browserErrors: errors }, null, 2));
  await browser.close();
})().catch(error => { console.error(error); process.exit(1); });

